#[derive(Debug, PartialEq, Eq)]
struct Config {
    host: String,
    port: i32,
}

fn main() {
    let a = Config {
        host: "localhost".into(),
        port: 8080,
    };
    let b = Config {
        host: "localhost".into(),
        port: 8080,
    };
    println!("{}", a == b);
